//! Messages as bytes, for a [`Bridge`](crate::Bridge): the [`Codec`] trait,
//! implemented by the user, and [`Wire`], generated by
//! [`topics!`](crate::topics) on every topic.
//!
//! A message travels as its subject, relative to the bridged channel, then its
//! payload: the segment ids, each parameter value as a length-prefixed
//! [`Codec`] encoding, then the message's encoding up to the end of the frame.

use crate::event::{self, Event};
use crate::nav::{Node, Path, Seg};
use crate::tree::{ParamValue, __param, __payload};
use std::any::Any;
use std::error::Error;
use std::fmt;

/// Error of a [`Codec`].
pub type CodecError = Box<dyn Error + Send + Sync>;

/// Turns values of type `M` into bytes and back: the messages and parameter
/// values of a bridged tree.
///
/// nattes has no serialization of its own. Implement this once for every
/// type your format handles, e.g. with serde and bincode:
///
/// ```ignore
/// struct Bincode;
///
/// impl<M: Serialize + DeserializeOwned> nattes::Codec<M> for Bincode {
///     fn encode(&self, value: &M, out: &mut Vec<u8>) -> Result<(), nattes::CodecError> {
///         bincode::serde::encode_into_std_write(value, out, bincode::config::standard())?;
///         Ok(())
///     }
///     fn decode(&self, bytes: &[u8]) -> Result<M, nattes::CodecError> {
///         Ok(bincode::serde::decode_from_slice(bytes, bincode::config::standard())?.0)
///     }
/// }
/// ```
///
/// Schema evolution is the codec's job: a value that fails to decode is
/// dropped. Change a message incompatibly under a new topic name instead.
pub trait Codec<M>: Send + Sync + 'static {
    /// Append the encoding of `value` to `out`.
    fn encode(&self, value: &M, out: &mut Vec<u8>) -> Result<(), CodecError>;
    /// The value encoded in all of `bytes`.
    fn decode(&self, bytes: &[u8]) -> Result<M, CodecError>;
}

/// Why a received message was dropped.
#[doc(hidden)]
#[derive(Debug)]
pub enum WireError {
    /// No topic of this tree has the subject: removed, renamed, or added by a
    /// newer version on the other side.
    UnknownTopic,
    /// The frame ends too early.
    Truncated,
    /// The codec failed.
    Codec(CodecError),
}

impl fmt::Display for WireError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            WireError::UnknownTopic => f.write_str("no topic has this subject"),
            WireError::Truncated => f.write_str("truncated frame"),
            WireError::Codec(error) => write!(f, "codec: {error}"),
        }
    }
}

impl Error for WireError {}

/// A topic whose messages a codec `C` can encode: implemented by
/// [`topics!`](crate::topics) on every `Topic` enum and leaf type, for every
/// `C` that implements [`Codec`] for the messages and parameters below it.
#[diagnostic::on_unimplemented(
    message = "`{C}` can't encode every message and parameter of `{Self}`",
    note = "implement `nattes::Codec<T>` on `{C}` for each message and parameter type of the tree"
)]
pub trait Wire<C>: Send + Sync + 'static {
    /// Append the parameters and the payload of an event, from the segments of
    /// its subject below this topic.
    #[doc(hidden)]
    fn encode(
        below: &[Seg],
        payload: &dyn Any,
        codec: &C,
        out: &mut Vec<u8>,
    ) -> Result<(), CodecError>;

    /// The event of the segment ids `ids` below this topic, whose subject so
    /// far is `path`, reading
    /// parameters and the payload from `bytes`.
    #[doc(hidden)]
    fn decode(path: Path, ids: &[u32], bytes: &mut &[u8], codec: &C) -> Result<Event, WireError>;
}

/// Append the parameter value of `seg`, length-prefixed.
#[doc(hidden)]
pub fn __encode_param<V: ParamValue, C: Codec<V>>(
    codec: &C,
    seg: &Seg,
    out: &mut Vec<u8>,
) -> Result<(), CodecError> {
    let mut value = Vec::new();
    codec.encode(__param::<V>(seg), &mut value)?;
    put_varint(out, value.len() as u64);
    out.extend_from_slice(&value);
    Ok(())
}

/// Read a length-prefixed parameter value.
#[doc(hidden)]
pub fn __decode_param<V, C: Codec<V>>(codec: &C, bytes: &mut &[u8]) -> Result<V, WireError> {
    let len = get_varint(bytes).ok_or(WireError::Truncated)? as usize;
    if bytes.len() < len {
        return Err(WireError::Truncated);
    }
    let (value, rest) = bytes.split_at(len);
    *bytes = rest;
    codec.decode(value).map_err(WireError::Codec)
}

/// Append the payload of a leaf's event.
#[doc(hidden)]
pub fn __encode_leaf<M: 'static, C: Codec<M>>(
    payload: &dyn Any,
    codec: &C,
    out: &mut Vec<u8>,
) -> Result<(), CodecError> {
    codec.encode(__payload::<M>(payload), out)
}

/// The event of a leaf on `path`, its payload being the rest of `bytes`.
#[doc(hidden)]
pub fn __decode_leaf<M: Send + Sync + 'static, C: Codec<M>>(
    path: Path,
    ids: &[u32],
    bytes: &mut &[u8],
    codec: &C,
) -> Result<Event, WireError> {
    if !ids.is_empty() {
        return Err(WireError::UnknownTopic);
    }
    let msg = codec.decode(bytes).map_err(WireError::Codec)?;
    *bytes = &[];
    Ok(event::imported(path, msg))
}

/// Append the frame body of `event` for a bridge on the channel of topic `T`
/// at depth `depth`: the relative segment ids, then the parameters and payload.
pub(crate) fn encode_event<T: Wire<C>, C>(
    event: &dyn crate::event::Envelope,
    depth: usize,
    codec: &C,
    out: &mut Vec<u8>,
) -> Result<(), CodecError> {
    let below = &event.path()[depth..];
    put_varint(out, below.len() as u64);
    for seg in below {
        out.extend_from_slice(&seg.id().to_le_bytes());
    }
    T::encode(below, event.payload(), codec, out)
}

/// The event of a frame body made by [`encode_event`], below `base`.
pub(crate) fn decode_event<T: Wire<C>, C>(
    base: &Node,
    mut bytes: &[u8],
    codec: &C,
) -> Result<Event, WireError> {
    let ids = get_ids(&mut bytes)?;
    T::decode(base.to_path(), &ids, &mut bytes, codec)
}

/// Read a count-prefixed list of segment ids.
pub(crate) fn get_ids(bytes: &mut &[u8]) -> Result<Vec<u32>, WireError> {
    let n = get_varint(bytes).ok_or(WireError::Truncated)? as usize;
    if bytes.len() < n * 4 {
        return Err(WireError::Truncated);
    }
    let (ids, rest) = bytes.split_at(n * 4);
    *bytes = rest;
    Ok(ids.as_chunks::<4>().0.iter().map(|id| u32::from_le_bytes(*id)).collect())
}


pub(crate) fn put_varint(out: &mut Vec<u8>, mut n: u64) {
    while n >= 0x80 {
        out.push(n as u8 | 0x80);
        n >>= 7;
    }
    out.push(n as u8);
}

pub(crate) fn get_varint(bytes: &mut &[u8]) -> Option<u64> {
    let mut n = 0u64;
    for shift in (0..64).step_by(7) {
        let (&byte, rest) = bytes.split_first()?;
        *bytes = rest;
        n |= u64::from(byte & 0x7f) << shift;
        if byte < 0x80 {
            return Some(n);
        }
    }
    None
}
